#include "MyVehiclePawn.h"
#include "Components/SkeletalMeshComponent.h"
#include "GameFramework/CharacterMovementComponent.h"

// Sets default values
AMyVehiclePawn::AMyVehiclePawn()
{
    // Set this pawn to call Tick() every frame.  You can turn this off to improve performance if you don't need it.
    PrimaryActorTick.bCanEverTick = true;

    VehicleMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("VehicleMesh"));
    RootComponent = VehicleMesh;

    SpringArm = CreateDefaultSubobject<USpringArmComponent>(TEXT("SpringArm"));
    SpringArm->SetupAttachment(RootComponent);
    SpringArm->TargetOffset = FVector(0.0f, 0.0f, 150.0f);
    SpringArm->bUsePawnControlRotation = true;

    Camera = CreateDefaultSubobject<UCameraComponent>(TEXT("Camera"));
    Camera->SetupAttachment(SpringArm, USpringArmComponent::SocketName);
}

// Called when the game starts or when spawned
void AMyVehiclePawn::BeginPlay()
{
    Super::BeginPlay();
}

// Called every frame
void AMyVehiclePawn::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);
}

// Throttle control function
void AMyVehiclePawn::SetThrottle(float Value)
{
    if (UChaosWheeledVehicleMovementComponent* VehicleMovement = Cast<UChaosWheeledVehicleMovementComponent>(GetVehicleMovement()))
    {
        VehicleMovement->SetThrottleInput(Value);
    }
}

// Steering control function
void AMyVehiclePawn::SetSteering(float Value)
{
    if (UChaosWheeledVehicleMovementComponent* VehicleMovement = Cast<UChaosWheeledVehicleMovementComponent>(GetVehicleMovement()))
    {
        VehicleMovement->SetSteeringInput(Value);
    }
}
